const request = request1;
const url = env.get("Endpoint") || '';
const bufferMsg = msg.payload;
msg.info = "";

function postMsg(payload) {
  const options = {
    method: 'POST',
    url,
    headers: { 'Content-Type': 'application/json' },
    rejectUnauthorized: false,
    body: JSON.stringify(payload),
    timeout: 30000
  };

  request(options, function (error, response) {
    if (error) {
      node.status({ fill: "red", shape: "ring", text: "Connection error..." });
      msg.payload = [];
      node.send(msg);
    } else if (response.statusCode === 200) {
      node.status({ fill: "blue", shape: "dot", text: `Message Post Success, StatusCode: ${response.statusCode}` });
      msg.payload = payload;
      msg.info = "sent.";
      node.send(msg);
    } else {
      node.status({ fill: "yellow", shape: "ring", text: `Message Post Failed, StatusCode: ${response.statusCode}` });
      msg.payload = [];
      node.send(msg);
    }
  });
}

if (Array.isArray(bufferMsg)) {
  if (bufferMsg.length >= 1) {
    const lastItem = bufferMsg[bufferMsg.length - 1];
    postMsg(lastItem);
  } else {
    node.status({ fill: "yellow", shape: "ring", text: "Waiting for messages to send" });
    msg.payload = [];
    node.send(msg);
  }
} else {
  node.status({ fill: "red", shape: "ring", text: "Payload must be an array" });
  msg.payload = [];
  node.send(msg);
}

if(msg.info == "sent."){
